(PKG/"live.py").write_text('from __future__ import annotations\nimport json,os,time,urllib.request\nfrom collections import defaultdict,Counter\n\nRPC_URL=os.getenv("SOLANA_RPC_URL","https://api.mainnet-beta.solana.com")\nWSOL="So11111111111111111111111111111111111111112"\nTARGET={"RAYDIUM_CLMM","RAYDIUM_CPMM","METEORA_DLMM","METEORA_DAMM_V2","ORCA"}\nPER_VENUE=int(os.getenv("QSB_044B_PER_VENUE","8"))\nMAX_SLOTS=int(os.getenv("QSB_044B_MAX_SLOTS","6"))\n\ndef _venue(v):\n    v=str(v or "")\n    return "METEORA_DAMM_V2" if v=="METEORA_DAMM" else v\n\ndef select_signatures(rows):\n    bysig=defaultdict(set);slots={}\n    for x in rows:\n        if not isinstance(x,dict) or not x.get("signature"):continue\n        v=_venue(x.get("venue"))\n        if v not in TARGET:continue\n        s=x["signature"];bysig[s].add(v)\n        try:slots[s]=int(x.get("slot"))\n        except Exception:continue\n    out=[];n=Counter()\n    for sig,vs in sorted(bysig.items(),key=lambda kv:slots.get(kv[0],0),reverse=True):\n        if len(vs)!=1:continue\n        v=next(iter(vs))\n        if n[v]>=PER_VENUE:continue\n        out.append((sig,v,slots[sig]));n[v]+=1\n    return out\n\ndef _rpc(method,params,timeout=20,retries=6):\n    body=json.dumps({"jsonrpc":"2.0","id":1,"method":method,"params":params}).encode()\n    last=None\n    for i in range(retries):\n        try:\n            req=urllib.request.Request(RPC_URL,data=body,headers={"content-type":"application/json","user-agent":"qseries-qsb044b/1.0"})\n            with urllib.request.urlopen(req,timeout=timeout) as r:\n                j=json.loads(r.read().decode())\n            if j.get("error"):raise RuntimeError("RPC_ERROR:"+json.dumps(j["error"]))\n            return j.get("result")\n        except Exception as e:\n            last=e\n            msg=str(e)\n            if "429" in msg and i+1<retries:\n                time.sleep(min(3.0,0.75*(i+1)));continue\n            if i+1<retries:\n                time.sleep(.35*(i+1));continue\n    raise last\n\ndef _tx_signature(tx):\n    try:\n        sigs=((tx.get("transaction") or {}).get("signatures") or [])\n        return sigs[0] if sigs else None\n    except Exception:return None\n\ndef hydrate_selected(selected,rpc_fn=_rpc):\n    # Fetch a handful of full blocks once, then recover many transactions locally.\n    wanted={s:(v,slot) for s,v,slot in selected}\n    slots=sorted({slot for _,_,slot in selected},reverse=True)[:MAX_SLOTS]\n    found={}\n    failures=[]\n    for slot in slots:\n        try:\n            b=rpc_fn("getBlock",[slot,{"encoding":"jsonParsed","transactionDetails":"full","rewards":False,"maxSupportedTransactionVersion":0}])\n            for tx in (b or {}).get("transactions") or []:\n                sig=_tx_signature(tx)\n                if sig in wanted:\n                    v,_=wanted[sig]\n                    # getBlock tx lacks top-level slot; attach exact block slot.\n                    x=dict(tx);x["slot"]=slot;found[sig]=(v,slot,x)\n            time.sleep(.12)\n        except Exception as e:\n            failures.append({"slot":slot,"error":f"{type(e).__name__}: {e}"})\n    return found,{"slots_requested":slots,"slot_count":len(slots),"block_failures":failures}\n\ndef _signer(tx):\n    for k in ((((tx or {}).get("transaction") or {}).get("message") or {}).get("accountKeys") or []):\n        if isinstance(k,dict) and k.get("signer"):return k.get("pubkey")\n    return None\n\ndef _balmap(rows,owner):\n    out={}\n    for b in rows or []:\n        if not isinstance(b,dict) or b.get("owner")!=owner:continue\n        m=b.get("mint");u=b.get("uiTokenAmount") or {}\n        try:a=float(u.get("uiAmountString") if u.get("uiAmountString") is not None else u.get("uiAmount"))\n        except Exception:continue\n        out[m]=out.get(m,0.0)+a\n    return out\n\ndef _native_delta(tx,owner):\n    msg=(((tx or {}).get("transaction") or {}).get("message") or {})\n    keys=msg.get("accountKeys") or []\n    idx=None\n    for i,k in enumerate(keys):\n        if isinstance(k,dict) and k.get("pubkey")==owner:idx=i;break\n    if idx is None:return None\n    meta=tx.get("meta") or {};pre=meta.get("preBalances") or [];post=meta.get("postBalances") or []\n    if idx>=len(pre) or idx>=len(post):return None\n    fee=int(meta.get("fee") or 0)\n    return (int(post[idx])-int(pre[idx])+fee)/1e9\n\ndef economic_from_tx(sig,venue,router_slot,tx):\n    if not isinstance(tx,dict) or (tx.get("meta") or {}).get("err") is not None:return None\n    owner=_signer(tx)\n    if not owner:return None\n    meta=tx.get("meta") or {}\n    pre=_balmap(meta.get("preTokenBalances"),owner);post=_balmap(meta.get("postTokenBalances"),owner)\n    ds={m:post.get(m,0.0)-pre.get(m,0.0) for m in set(pre)|set(post)}\n    ds={m:d for m,d in ds.items() if abs(d)>1e-12}\n    neg=[(m,-d) for m,d in ds.items() if d<0];pos=[(m,d) for m,d in ds.items() if d>0]\n    try:slot=int(tx.get("slot",router_slot))\n    except Exception:return None\n    base={"venue":venue,"slot":slot,"signature":sig,"pool":None,"source_module":"qsb_044b_slot_block_hydration","execution_authority":False}\n    if len(neg)==1 and len(pos)==1:\n        im,ia=neg[0];om,oa=pos[0]\n        return {**base,"input_mint":im,"output_mint":om,"input_amount":ia,"output_amount":oa,\n                "decoder_state":"EXACT_SINGLE_VENUE_SIGNER_TOKEN_DELTA","discovery_quality":"EXACT_TOKEN_TOKEN"}\n    nd=_native_delta(tx,owner)\n    if nd is not None and abs(nd)>=0.00001:\n        if len(pos)==1 and len(neg)==0 and nd<0:\n            om,oa=pos[0]\n            return {**base,"input_mint":WSOL,"output_mint":om,"input_amount":abs(nd),"output_amount":oa,\n                    "decoder_state":"DISCOVERY_NATIVE_SOL_DELTA","discovery_quality":"REQUOTE_REQUIRED"}\n        if len(neg)==1 and len(pos)==0 and nd>0:\n            im,ia=neg[0]\n            return {**base,"input_mint":im,"output_mint":WSOL,"input_amount":ia,"output_amount":nd,\n                    "decoder_state":"DISCOVERY_NATIVE_SOL_DELTA","discovery_quality":"REQUOTE_REQUIRED"}\n    return None\n\ndef hydrate(router_rows,rpc_fn=_rpc):\n    sel=select_signatures(router_rows)\n    txs,block_meta=hydrate_selected(sel,rpc_fn)\n    attempted=Counter(v for _,v,_ in sel);exact=Counter();native=Counter();rej=Counter();rows=[]\n    for sig,v,slot in sel:\n        z=txs.get(sig)\n        if not z:rej[v]+=1;continue\n        x=economic_from_tx(sig,v,slot,z[2])\n        if not x:rej[v]+=1;continue\n        rows.append(x)\n        if x["discovery_quality"]=="EXACT_TOKEN_TOKEN":exact[v]+=1\n        else:native[v]+=1\n    return {"rows":rows,"attempted":dict(attempted),"exact_token_token":dict(exact),\n            "native_sol_discovery":dict(native),"rejected":dict(rej),"block_hydration":block_meta}\n',encoding="utf-8")
(PKG/"runtime.py").write_text('from pathlib import Path\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.mriya_executable_requote.gate import build\ndef main():\n    print("[QSB-044] BROAD SAME-WINDOW EXECUTABLE HUNTER",flush=True)\n    print("[DISCOVERY] exact token-token + fee-adjusted native-SOL signer deltas",flush=True)\n    print("[VALIDATION] every surfaced route must survive QSB-042 executable Jupiter leg re-quote",flush=True)\n    print("[MODE] execution_authority=FALSE",flush=True)\n    build(Path.cwd())\nif __name__=="__main__":main()\n',encoding="utf-8")
(BPKG/"bridge.py").write_text('from __future__ import annotations\nimport asyncio,importlib,json\nfrom collections import Counter\nfrom pathlib import Path\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.mriya_broad_same_window.live import hydrate\n\nPKG="qseries_v2.oracle_strategy_intelligence.solana_universal_trade_tape"\nROUTER=f"{PKG}.usls_046b_shared_multidex_live_event_router"\nID=f"{PKG}.usls_047c_batched_retry_safe_multidex_identity_resolver"\nPUMP=f"{PKG}.usls_048b_shared_universal_economic_normalizer"\nREPAIR=f"{PKG}.usls_101d_pumpswap_048b_direct_rematerialization_repair"\nMAX_AGE=4\n\ndef _rows(o):\n    if isinstance(o,list):return [x for x in o if isinstance(x,dict)]\n    out=[]\n    if isinstance(o,dict):\n        for k in ("rows","exact_rows","trades","exact_trades","economic_rows","universal_trades"):\n            if isinstance(o.get(k),list):out.extend(x for x in o[k] if isinstance(x,dict))\n    return out\n\ndef _call(name,root):\n    m=importlib.import_module(name);errs=[]\n    for fnn in ("write","build","repair","rematerialize","exact_rows"):\n        fn=getattr(m,fnn,None)\n        if not callable(fn):continue\n        try:\n            x=fn(root)\n            if isinstance(x,tuple) and len(x)>1 and isinstance(x[1],dict):return x[1]\n            if isinstance(x,(dict,list)):return x\n        except Exception as e:errs.append(f"{fnn}:{type(e).__name__}:{e}")\n    raise RuntimeError("; ".join(errs) if errs else "NO_PRODUCER")\n\nasync def _capture():\n    return await importlib.import_module(ROUTER).capture(seconds=3,max_rows=2800)\n\ndef build(root):\n    root=Path(root);live=asyncio.run(_capture());rr=list((live or {}).get("rows") or [])\n    slots=[]\n    for x in rr:\n        try:slots.append(int(x.get("slot")))\n        except Exception:pass\n    mx=max(slots) if slots else None\n    print(f"[LIVE_ROUTER] rows={len(rr)} max_slot={mx}",flush=True)\n    pump=[]\n    try:_call(ID,root)\n    except Exception as e:print("[PUMP_ID_FAIL]",e,flush=True)\n    for mod in (PUMP,REPAIR):\n        try:pump.extend(_rows(_call(mod,root)))\n        except Exception as e:print("[PUMP_ECON_FAIL]",mod.rsplit(".",1)[-1],e,flush=True)\n    h=hydrate(rr)\n    print("[HYDRATE_ATTEMPTED] "+json.dumps(h["attempted"],sort_keys=True),flush=True)\n    print("[EXACT_TOKEN_TOKEN] "+json.dumps(h["exact_token_token"],sort_keys=True),flush=True)\n    print("[NATIVE_SOL_DISCOVERY] "+json.dumps(h["native_sol_discovery"],sort_keys=True),flush=True)\n    print("[HYDRATE_REJECTED] "+json.dumps(h["rejected"],sort_keys=True),flush=True)\n    econ=[];seen=set()\n    for x in pump+h["rows"]:\n        if not isinstance(x,dict):continue\n        if not all(k in x for k in ("venue","input_mint","output_mint","input_amount","output_amount","slot")):continue\n        try:slot=int(x["slot"]);ia=float(x["input_amount"]);oa=float(x["output_amount"])\n        except Exception:continue\n        if ia<=0 or oa<=0:continue\n        k=(x["venue"],x.get("signature"),x["input_mint"],x["output_mint"],ia,oa,slot)\n        if k in seen:continue\n        seen.add(k);y=dict(x);y["slot"]=slot;econ.append(y)\n    fresh=[]\n    for x in econ:\n        if mx is None:continue\n        age=mx-x["slot"];x["slot_age"]=age\n        if 0<=age<=MAX_AGE:fresh.append(x)\n    vc=Counter(x["venue"] for x in fresh)\n    print("[ECONOMIC_COUNTS] "+json.dumps(dict(sorted(vc.items())),sort_keys=True),flush=True)\n    print(f"[BRIDGE] total_economic={len(econ)} fresh_economic={len(fresh)}",flush=True)\n    out={"revision":"QSB_044","live_router_rows":len(rr),"live_max_slot":mx,"fresh_economic_rows":fresh,\n         "fresh_venue_counts":dict(vc),"hydration":h,"execution_authority":False,\n         "truth":"BROAD_SAME_WINDOW_DISCOVERY_ROWS_REQUIRE_QSB042_EXECUTABLE_REQUOTE"}\n    p=root/"runtime_state/qseries/qsb044_broad_same_window/report.json";p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(out,indent=2),encoding="utf-8")\n    return out\n',encoding="utf-8")
(ROOT/"test_qsb_044b_slot_block_hydration_repair.py").write_text('import unittest\nfrom qseries_v2.oracle_strategy_intelligence.solana_money.mriya_broad_same_window import live\nWSOL=live.WSOL\n\ndef block_tx(sig="S"):\n    return {"transaction":{"signatures":[sig],"message":{"accountKeys":[{"pubkey":"W","signer":True}]}},\n            "meta":{"err":None,"fee":5000,"preBalances":[2000000000],"postBalances":[1499995000],\n                    "preTokenBalances":[{"owner":"W","mint":"T","uiTokenAmount":{"uiAmountString":"0"}}],\n                    "postTokenBalances":[{"owner":"W","mint":"T","uiTokenAmount":{"uiAmountString":"100"}}]}}\n\nclass T(unittest.TestCase):\n    def test_block_hydrates_many_without_gettransaction(self):\n        sel=[("S1","ORCA",10),("S2","RAYDIUM_CLMM",10)]\n        def rpc(method,params):\n            self.assertEqual(method,"getBlock")\n            return {"transactions":[block_tx("S1"),block_tx("S2")]}\n        got,meta=live.hydrate_selected(sel,rpc)\n        self.assertEqual(set(got),{"S1","S2"});self.assertEqual(meta["slot_count"],1)\n        print("[PASS] one block RPC hydrates multiple selected signatures")\n    def test_native_sol_discovery(self):\n        x=dict(block_tx("S"));x["slot"]=10\n        e=live.economic_from_tx("S","ORCA",10,x)\n        self.assertEqual(e["input_mint"],WSOL);self.assertEqual(e["discovery_quality"],"REQUOTE_REQUIRED")\n        print("[PASS] native SOL route discovery preserved")\n    def test_multivenue_signature_still_rejected(self):\n        rs=[{"signature":"S","venue":"ORCA","slot":10},{"signature":"S","venue":"METEORA_DLMM","slot":10}]\n        self.assertFalse(live.select_signatures(rs))\n        print("[PASS] multi-venue attribution guard preserved")\n    def test_slot_cap(self):\n        sel=[(f"S{i}","ORCA",100-i) for i in range(12)]\n        calls=[]\n        def rpc(method,params):\n            calls.append(params[0]);return {"transactions":[]}\n        _,m=live.hydrate_selected(sel,rpc)\n        self.assertLessEqual(m["slot_count"],live.MAX_SLOTS)\n        print("[PASS] bounded slot-block RPC fanout")\nif __name__=="__main__":unittest.main(verbosity=2)\n',encoding="utf-8")
